1	export type Cell = [number, number];
2	
3	function isSameCell([x, y]: Cell, [otherX, otherY]: Cell): boolean {
4	  return x === otherX && y === otherY;
5	}
6	
7	function isNeighbor(cell: Cell, other: Cell): boolean {
8	  const [x, y] = cell;
9	  const [otherX, otherY] = other;
10	  return (
11	    !isSameCell(cell, other) &&
12	    Math.abs(x - otherX) <= 1 &&
13	    Math.abs(y - otherY) <= 1
14	  );
15	}
16	
17	function countNeighbors(cell: Cell, liveCells: Cell[]): number {
18	  return liveCells.filter((other) => isNeighbor(cell, other)).length;
19	}
20	
21	function uniqueCells(cells: Cell[]): Cell[] {
22	  return cells.filter(
23	    (cell, index) => cells.findIndex((other) => isSameCell(cell, other)) === index
24	  );
25	}
26	
27	function isAlive(cell: Cell, liveCells: Cell[]): boolean {
28	  return liveCells.some((live) => isSameCell(cell, live));
29	}
30	
31	function neighborsOf(cell: Cell): Cell[] {
32	  const [x, y] = cell;
33	  const offsets = [-1, 0, 1];
34	  return offsets
35	    .flatMap((dx) => offsets.map((dy): Cell => [x + dx, y + dy]))
36	    .filter((candidate) => !isSameCell(cell, candidate));
37	}
38	
39	// Conway's four rules, expressed as the two outcomes that produce a live cell.
40	// Both are total predicates: each states its own aliveness precondition, so
41	// either can be asked of any cell without the caller having to pre-filter.
42	function survives(cell: Cell, liveCells: Cell[]): boolean {
43	  const neighbors = countNeighbors(cell, liveCells);
44	  return isAlive(cell, liveCells) && (neighbors === 2 || neighbors === 3);
45	}
46	
47	function isBorn(cell: Cell, liveCells: Cell[]): boolean {
48	  const neighbors = countNeighbors(cell, liveCells);
49	  return !isAlive(cell, liveCells) && neighbors === 3;
50	}
51	
52	// Only live cells and their immediate neighbors can be live next generation;
53	// every other cell is dead with 0 neighbors and stays dead.
54	function candidateCells(liveCells: Cell[]): Cell[] {
55	  return uniqueCells([...liveCells, ...liveCells.flatMap(neighborsOf)]);
56	}
57	
58	export function nextGeneration(liveCells: Cell[]): Cell[] {
59	  return candidateCells(liveCells).filter(
60	    (cell) => survives(cell, liveCells) || isBorn(cell, liveCells)
61	  );
62	}
