function survives(cell: Cell, liveCells: Cell[]): boolean {
  const neighborCount = countNeighbors(cell, liveCells);
  return (
    isAlive(cell, liveCells) && (neighborCount === 2 || neighborCount === 3)
  );
}

function isBorn(cell: Cell, liveCells: Cell[]): boolean {
  const neighborCount = countNeighbors(cell, liveCells);
  return !isAlive(cell, liveCells) && neighborCount === 3;
}
